+	data, err := os.ReadFile(excludePath) //nolint:gosec // path is derived from git dir
+	if err == nil {
+		for _, line := range strings.Split(string(data), "\n") {
+			if strings.TrimSpace(line) == relPath {
+				return nil
+			}
+		}
+	} else if !os.IsNotExist(err) {
